private boolean isAllEmpty() {
    int size;
    ArrayList<ArrayList<TimeBarInfo>> arrayList = this.enableTimeBarInfoList;
    if (arrayList != null) {
        Iterator<ArrayList<TimeBarInfo>> it = arrayList.iterator();
        size = 0;
        while (it.hasNext()) {
            size += it.next().size();
        }
    } else {
        size = 0;
    }
    return size == 0;
}
